extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var basket_source := source_of("res://basket.gd")
	check("no_ui_label", not basket_source.contains("ui_label"), "basket.gd non deve più fare riferimento a ui_label")

	var basket := await instantiate_scene("res://basket.tscn")
	if not check("basket_ok", basket != null, "basket.tscn deve istanziarsi correttamente"):
		return

	var hud := find_by_name(basket, "HUD") as CanvasLayer
	if not check("hud_in_basket", hud != null, "HUD deve essere istanziato dentro basket.tscn"):
		return

	var score_lbl := find_by_name(hud, "ScoreLabel") as Label
	var lives_box := find_by_name(hud, "LivesContainer") as HBoxContainer
	if not check("elementi_hud", score_lbl != null and lives_box != null, "ScoreLabel e LivesContainer devono essere presenti nell'HUD"):
		return

	await wait_frames(2)
	var initial_score = int(get_prop(basket, "score", 0))
	check("score_iniziale", score_lbl.text == "Punti: " + str(initial_score), "All'avvio il punteggio mostrato deve corrispondere a quello del gioco")

	var test_points := 50
	call_if_exists(basket, "add_score", [test_points])
	await wait_frames(2)
	var current_score = int(get_prop(basket, "score", test_points))
	check("score_dopo_aggiunta", score_lbl.text == "Punti: " + str(current_score), "Dopo add_score l'HUD deve mostrare il punteggio aggiornato")

	var initial_lives := int(get_prop(basket, "lives", 3))
	call_if_exists(basket, "take_damage", [1])
	await wait_frames(2)
	var expected_lives := int(get_prop(basket, "lives", initial_lives - 1))
	var icons: Array[Node] = lives_box.get_children()
	if check("icone_presenti", icons.size() > 0, "LivesContainer deve avere delle icone vita"):
		var visible_count := 0
		for node in icons:
			var item := node as CanvasItem
			if item != null and item.visible:
				visible_count += 1
		check("vite_aggiornate_hud", visible_count == expected_lives, "Il numero di icone vita visibili nell'HUD deve corrispondere alle vite del carrello (%d)" % expected_lives)
